import { gql } from "@apollo/client";

export const GET_SHELL = gql`
  query GetShell($id: ID!) {
    node(id: $id) {
      ... on Shell {
        id
        closedAt
        owner {
          id
          name
        }
        beacon {
          id
          name
          principal
          agentIdentifier
          interval
          transport
          host {
            id
            name
            primaryIP
            externalIP
            platform
            tags {
              edges {
                node {
                  id
                  name
                  kind
                }
              }
            }
          }
        }
        portals {
          id
          closedAt
        }
        pivots {
          edges {
            node {
              id
              kind
              destination
              closedAt
            }
          }
        }
      }
    }
  }
`;

export const GET_BEACON_STATUS = gql`
  query GetBeaconStatus($id: ID!) {
    node(id: $id) {
      ... on Beacon {
        lastSeenAt
        nextSeenAt
        interval
      }
    }
  }
`;

export const GET_PORTAL_STATUS = gql`
  query GetPortalStatus($id: ID!) {
    node(id: $id) {
      ... on Portal {
        closedAt
      }
    }
  }
`;

export const CLOSE_PORTAL_MUTATION = gql`
  mutation ClosePortal($id: ID!) {
    closePortal(portalID: $id) {
      id
      closedAt
    }
  }
`;

export const GET_SHELL_ACTIVE_USERS = gql`
  query GetShellActiveUsers($id: ID!) {
    node(id: $id) {
      ... on Shell {
        activeUsers {
          edges {
            node {
              id
              name
              photoURL
            }
          }
        }
      }
    }
  }
`;
